<script>
(function() {
  var megaTrigger = document.querySelector('[data-mega-trigger]');
  var megaMenu = document.getElementById('megaMenu');
  var megaTimeout, megaOpen = false;
  function openMega() { clearTimeout(megaTimeout); megaMenu.classList.add('open'); megaOpen = true; }
  function closeMega() { megaTimeout = setTimeout(function() { megaMenu.classList.remove('open'); megaOpen = false; }, 200); }
  if (megaTrigger && megaMenu) {
    megaTrigger.addEventListener('mouseenter', openMega);
    megaTrigger.addEventListener('click', function(e) { e.preventDefault(); megaOpen ? closeMega() : openMega(); });
    megaMenu.addEventListener('mouseenter', function() { clearTimeout(megaTimeout); });
    megaMenu.addEventListener('mouseleave', closeMega);
  }

  var hamburger = document.getElementById('hamburger');
  var mobileNav = document.getElementById('mobileNav');
  if (hamburger && mobileNav) {
    hamburger.addEventListener('click', function() {
      var isOpen = mobileNav.classList.contains('open');
      if (isOpen) { mobileNav.classList.remove('open'); hamburger.classList.remove('open'); }
      else { mobileNav.classList.add('open'); hamburger.classList.add('open'); }
    });
    document.querySelectorAll('[data-mobile-sub]').forEach(function(trigger) {
      trigger.addEventListener('click', function(e) {
        e.preventDefault();
        var target = document.getElementById(this.getAttribute('data-mobile-sub'));
        var isOpen = this.classList.contains('open');
        document.querySelectorAll('.mobile-nav-trigger.open').forEach(function(t) { t.classList.remove('open'); });
        document.querySelectorAll('.mobile-subnav.open').forEach(function(s) { s.classList.remove('open'); });
        if (!isOpen) { this.classList.add('open'); if (target) target.classList.add('open'); }
      });
    });
  }

  var header = document.getElementById('header');
  window.addEventListener('scroll', function() {
    header.style.boxShadow = window.pageYOffset > 100 ? '0 4px 20px rgba(0,0,0,0.3)' : 'none';
  });

  document.addEventListener('keydown', function(e) {
    if (e.key === 'Escape' && mobileNav && mobileNav.classList.contains('open')) {
      mobileNav.classList.remove('open');
      if (hamburger) hamburger.classList.remove('open');
    }
  });
})();
</script>
